public int active()
{
    int ret = true;

    ret = next active();

    FormFunctionButtonControl control = this.formRun().design().controlName(formControlStr(CustTable, FTDBookMenuItemButton));
    CustTable activeCustTable = this.cursor();

    control.enabled(activeCustTable.FTDBookTable != 0);

    return ret;
}
